// ../core/src/systems/mesh-system.ts
function getMeshModel(meshComponent) {
  switch (meshComponent.model) {
    case "PlaneMesh": {
      meshComponent.geometry = new PlaneGeometry(20, 20, 20, 20);
      meshComponent.material = new MeshStandardNodeMaterial({ color: "#5dc278" });
      return new Mesh(meshComponent.geometry, meshComponent.material);
    }
    case "BoxMesh": {
      const geometry = new BoxGeometry(1, 1, 1);
      const material = new MeshBasicNodeMaterial({ color: 65280, side: DoubleSide });
      return new Mesh(geometry, material);
    }
    default: {
      const modelLoaded = resourcesLoader.resources.models.get(
        meshComponent.name
      );
      return modelLoaded.scene ? modelLoaded.scene.clone() : modelLoaded.clone();
    }
  }
}
var fogPlane = new Vector4();
function getFoggyMaterial(fogDepth, fogColor, color4, side) {
  let material = new MeshStandardMaterial({ color: color4, side, metalness: 0.5, roughness: 0.75 });
  material.onBeforeCompile = (shader) => {
    shader.uniforms.fPlane = { value: fogPlane };
    shader.uniforms.fDepth = { value: fogDepth };
    shader.uniforms.fColor = { value: new Color(fogColor) };
    shader.fragmentShader = `
      uniform vec4 fPlane;
      uniform float fDepth;
      uniform vec3 fColor;
    ` + shader.fragmentShader;
    shader.fragmentShader = shader.fragmentShader.replace(
      `#include <clipping_planes_fragment>`,
      `#include <clipping_planes_fragment>
      float planeFog = 0.0;
      planeFog = smoothstep(0.0, -fDepth, dot( vViewPosition, fPlane.xyz) - fPlane.w);
      `
    );
    shader.fragmentShader = shader.fragmentShader.replace(
      `#include <fog_fragment>`,
      `#include <fog_fragment>
       gl_FragColor.rgb = mix( gl_FragColor.rgb, fColor, planeFog );
      `
    );
  };
  return material;
}
var MeshSystem = class extends AbstractSystem {
  name = "MeshSystem";
  async start(deltaTime3) {
    spelDebug.log("[Mesh System]::Start");
    this.queryComponents = [
      "mesh" /* Mesh */,
      "transform" /* Transform */
    ];
    const scenes = this.context.sceneManager.renderScenes;
    if (scenes.length === 0) {
      return;
    }
    scenes.forEach((scene) => {
      var fogDepth = 200;
      var fogColor = 16777215;
      const fog3 = new Mesh(new BoxGeometry(50, 50, 50), getFoggyMaterial(fogDepth, fogColor, 4210752, FrontSide));
      scene.addChild(fog3);
    });
  }
  async run() {
    const scenes = this.context.sceneManager.renderScenes;
    if (scenes.length === 0) {
      return;
    }
    scenes.forEach((scene) => {
      this.query("add").filter((entity2) => entity2.visible).forEach(
        (entity2) => {
          const meshComponent = entity2.components.get("mesh" /* Mesh */);
          const { position: { x: x2, y: y3, z: z2 }, rotation, scale } = entity2.components.get(
            "transform" /* Transform */
          );
          console.log(meshComponent.instance);
          if (!meshComponent.instance) {
            console.log("WILL CREATE MESH");
            if (meshComponent.instanced) {
              const matrix = new Matrix4();
              getMeshModel(meshComponent);
              meshComponent.instance = new InstancedMesh(
                meshComponent.geometry,
                meshComponent.material,
                meshComponent.instanced.amount
              );
              scene.instance.add(meshComponent.instance);
            } else {
              meshComponent.instance = getMeshModel(meshComponent);
              scene.instance.add(meshComponent.instance);
            }
          }
          if (meshComponent.instance) {
            meshComponent.instance.traverse((model) => {
              if (model.isMesh) {
                model.castShadow = true;
                model.receiveShadow = true;
              }
            });
            meshComponent.instance?.setRotationFromEuler(
              new Euler(
                MathUtils.degToRad(rotation.x),
                rotation.y * Math.PI / 180,
                MathUtils.degToRad(rotation.z),
                "XYZ"
              )
            );
            meshComponent.instance?.position.set(x2, y3, z2);
            if (meshComponent.instance?.type === "Mesh") {
              meshComponent.instance.scale.set(scale.x, scale.y, scale.z);
            } else {
              meshComponent.instance?.children[0].scale.set(scale.x, scale.y, scale.z);
            }
          }
        }
      );
      this.query("update").filter((entity2) => entity2.visible).forEach(
        (entity2) => {
          const meshComponent = entity2.components.get(
            "mesh" /* Mesh */
          );
          const { position: { x: x2, y: y3, z: z2 }, rotation, scale } = entity2.components.get(
            "transform" /* Transform */
          );
          if (meshComponent.instance) {
            if (meshComponent.instance?.type === "Mesh") {
              meshComponent.instance.scale.set(scale.x, scale.y, scale.z);
            } else {
              meshComponent.instance?.children[0].scale.set(scale.x, scale.y, scale.z);
            }
            meshComponent.instance?.setRotationFromEuler(
              new Euler(
                MathUtils.degToRad(rotation.x),
                rotation.y * Math.PI / 180,
                MathUtils.degToRad(rotation.z),
                "XYZ"
              )
            );
          }
        }
      );
      this.query("remove").forEach(
        (entity2) => {
          console.log("REMOVING MESH");
          const meshComponent = entity2.components.get(
            "mesh" /* Mesh */
          );
          const { position: { x: x2, y: y3, z: z2 }, rotation, scale } = entity2.components.get(
            "transform" /* Transform */
          );
          if (meshComponent.instance) {
            meshComponent.instance.traverse((model) => {
              if (model.isMesh && meshComponent.instance.geometry) {
                meshComponent.instance.geometry.dispose();
              }
            });
            scene.instance.remove(meshComponent.instance);
            meshComponent.instance = void 0;
          }
        }
      );
    });
  }
};

