var CameraSystem = class extends AbstractSystem {
  name = "CameraSystem";
  async start(deltaTime3) {
    spelDebug.log("[Camera System]::Start");
  }
  async run(deltaTime3) {
    const scenes = this.context.sceneManager.renderScenes;
    if (scenes.length === 0) {
      return;
    }
    const camerasToRender = this.getCameras(scenes);
    const views = this.generateCameraPosition(camerasToRender);
    let index = 0;
    for (const { camera, transform, scene } of camerasToRender) {
      const { position, rotation } = transform;
      if (!camera.instance) {
        camera.instance = this.generateCamera(camera);
        scene.instance.add(camera.instance);
        if (camera.follow) {
          const followEntity = scene.entitiesManager.getByName(camera.follow);
          const followSprite = followEntity?.getComponent("sprite" /* Sprite */);
          if (followSprite && followSprite.instance) {
            followSprite.instance.add(camera.instance);
          }
        }
        if (camera.lookAt && !camera.lookAtSet) {
          const lookAtEntity = scene.entitiesManager.getByName(camera.lookAt);
          const lookAtSprite = lookAtEntity?.getComponent("sprite" /* Sprite */);
          if (lookAtSprite && lookAtSprite.instance) {
            camera.instance.lookAt(lookAtSprite.instance.position);
            camera.lookAtSet = true;
          }
        } else {
          const lookAtEntity = scene.entitiesManager.getByName(camera.lookAt);
          const lookAtSprite = lookAtEntity?.getComponent("sprite" /* Sprite */);
          if (lookAtSprite && lookAtSprite.instance) {
            camera.instance.lookAt(lookAtSprite.instance.position);
          }
        }
        if (camera.background) {
        }
        const skyColor = color2(15791605);
        const groundColor = color2(13688551);
        const fogNoiseDistance = positionView2.z.negate().smoothstep(0, camera.far - 300);
        const distance3 = fogNoiseDistance.mul(20).max(3.5);
        const alpha = 0.98;
        const groundFogArea = float2(distance3).sub(positionWorld2.y).div(distance3).pow(3).saturate().mul(alpha);
        const timer = uniform2(0).onFrameUpdate((frame) => frame.time);
        const fogNoiseA = triNoise3D2(positionWorld2.mul(5e-3), 0.2, timer);
        const fogNoiseB = triNoise3D2(positionWorld2.mul(0.01), 0.2, timer.mul(1.2));
        const fogNoise = fogNoiseA.add(fogNoiseB).mul(groundColor);
        scene.instance.fogNode = fog2(fogNoiseDistance.oneMinus().mix(groundColor, fogNoise), groundFogArea);
        scene.instance.backgroundNode = normalWorld2.y.max(0).mix(groundColor, skyColor);
      }
      const left = Math.floor(globalThis.innerWidth * views[index].left);
      const bottom = Math.floor(globalThis.innerHeight * views[index].bottom);
      const width = Math.floor(globalThis.innerWidth * views[index].width);
      const height = Math.floor(globalThis.innerHeight * views[index].height);
      this.context.renderer.setViewport(left, bottom, width, height);
      this.context.renderer.setScissor(left, bottom, width, height);
      this.context.renderer.setScissorTest(true);
      if (camera.instance instanceof OrthographicCamera) {
        camera.instance.left = width / -camera.factor;
        camera.instance.right = width / camera.factor;
        camera.instance.top = height / camera.factor;
        camera.instance.bottom = height / -camera.factor;
      }
      if (camera.instance instanceof PerspectiveCamera) {
        camera.instance.aspect = width / height;
      }
      camera.instance.position.x = position.x;
      camera.instance.position.y = position.y;
      camera.instance.position.z = position.z;
      camera.instance.setRotationFromEuler(
        new Euler(
          rotation.x * Math.PI / 180,
          rotation.y * Math.PI / 180,
          rotation.z * Math.PI / 180,
          "XYZ"
        )
      );
      camera.instance.updateProjectionMatrix();
      index += 1;
      scene.addCamera(camera);
      await this.context.renderer.renderAsync(scene.instance, camera.instance);
    }
  }
  getCameras(scenes) {
    let camerasData = [];
    scenes.forEach((scene) => {
      const validEntities = scene.entitiesManager.getAllWithComponents(
        "camera" /* Camera */
      );
      camerasData = [
        ...camerasData,
        ...validEntities.map((entity2) => ({
          camera: entity2.components.get("camera" /* Camera */),
          transform: entity2.components.get("transform" /* Transform */),
          scene
        }))
      ];
    });
    return camerasData;
  }
  generateCamera({ projection, fov: fov2, near, far }) {
    const { clientWidth, clientHeight } = document.body;
    if (projection === "orthographic") {
      return new OrthographicCamera(
        clientWidth / -2,
        clientWidth / 2,
        clientHeight / 2,
        clientHeight / -2,
        near,
        far
      );
    } else {
      return new PerspectiveCamera(
        fov2,
        clientWidth / clientHeight,
        near,
        far
      );
    }
  }
  generateCameraPosition(cameras) {
    const size = 2;
    const rows = [];
    for (let i2 = 0; i2 < cameras.length; i2 += size) {
      rows.push([...cameras.slice(i2, i2 + size)]);
    }
    const data = [];
    for (let n2 = 0; n2 < rows.length; n2++) {
      for (let y3 = 0; y3 < rows[n2].length; y3++) {
        data.push({
          width: 0 + 1 / rows[n2].length,
          height: 0 + 1 / rows.length,
          left: y3 === 0 ? 0 : 0 + 1 / (y3 + 1),
          bottom: n2 === 0 ? 0 : 0 + 1 / (n2 + 1)
        });
      }
    }
    return data;
  }
};

// ../core/src/systems/sprite-system.ts
var SpriteSystem = class extends AbstractSystem {
  name = "SpriteSystem";
  async start(deltaTime3) {
    spelDebug.log("[Sprite System]::Start");
    this.queryComponents = [
      "sprite" /* Sprite */,
      "transform" /* Transform */
    ];
  }
  async run() {
    const scenes = this.context.sceneManager.renderScenes;
    if (scenes.length === 0) {
      return;
    }
    scenes.forEach((scene) => {
      this.query("add").filter((entity2) => entity2.visible).forEach(
        (entity2) => {
          const spriteComponent = entity2.components.get("sprite" /* Sprite */);
          const scriptsComponent = entity2.components.get("script" /* Script */);
          const transformComponent = entity2.components.get(
            "transform" /* Transform */
          );
          const { position: { x: x2, y: y3, z: z2 }, rotation, scale } = transformComponent;
          if (spriteComponent.instance == null) {
            spriteComponent.spriteMap = resourcesLoader.resources.images.get(
              spriteComponent.source
            );
            const { width, height } = spriteComponent;
            const columns = spriteComponent.spriteMap.source.data.width / width;
            const rows = spriteComponent.spriteMap.source.data.height / height;
            spriteComponent.spriteMap.userData.columns = columns;
            spriteComponent.spriteMap.userData.rows = rows;
            if (!spriteComponent.flipX) {
              spriteComponent.spriteMap.repeat.set(1 / columns, 1 / rows);
              spriteComponent.spriteMap.center = new Vector2(0, 1);
            } else {
              spriteComponent.spriteMap.repeat.set(-1 / columns, 1 / rows);
              spriteComponent.spriteMap.center = new Vector2(1, 1);
            }
            spriteComponent.spriteMap.offset.x = 1 / columns * (spriteComponent.column - 1);
            spriteComponent.spriteMap.offset.y = 1 / rows * (spriteComponent.row - 1);
            if (spriteComponent.pixelPerfect) {
              spriteComponent.spriteMap.minFilter = LinearFilter;
              spriteComponent.spriteMap.magFilter = NearestFilter;
            }
            spriteComponent.spriteMap.wrapS = RepeatWrapping;
            spriteComponent.spriteMap.wrapT = RepeatWrapping;
            spriteComponent.spriteMaterial = new MeshStandardNodeMaterial({
              map: spriteComponent.spriteMap,
              alphaMap: spriteComponent.spriteMap,
              alphaTest: 0.05,
              side: 2
            });
            spriteComponent.spriteGeometry = new PlaneGeometry(
              this.getScaled(width),
              this.getScaled(height),
              1,
              1
            );
            const instance3 = true;
            if (spriteComponent.source === "grass") {
              const matrix = new Matrix4();
              spriteComponent.instance = new InstancedMesh(
                spriteComponent.spriteGeometry,
                spriteComponent.spriteMaterial,
                100
              );
              for (let i2 = 0; i2 < 10; i2++) {
                this.randomizeMatrix(matrix);
                spriteComponent.instance.setMatrixAt(i2, matrix);
              }
              scene.instance.add(spriteComponent.instance);
            } else {
              spriteComponent.instance = new Mesh(
                spriteComponent.spriteGeometry,
                spriteComponent.spriteMaterial
              );
              spriteComponent.instance.traverse((model) => {
                model.castShadow = true;
              });
              spriteComponent.instance.visible = entity2.visible;
              scene.instance.add(spriteComponent.instance);
            }
          } else {
            scene.instance.add(spriteComponent.instance);
          }
          spriteComponent.instance?.scale.set(scale.x, scale.y, scale.z);
          spriteComponent.instance?.position.set(
            x2,
            y3,
            z2
          );
        }
      );
      this.query("update").filter((entity2) => entity2.visible).forEach(
        (entity2) => {
          const spriteComponent = entity2.components.get("sprite" /* Sprite */);
          const { position: { x: x2, y: y3, z: z2 }, rotation } = entity2.components.get(
            "transform" /* Transform */
          );
          const rotationEuler = new Euler().setFromQuaternion(
            new Quaternion(
              rotation.x,
              rotation.y,
              rotation.z,
              // deno-lint-ignore ban-ts-comment
              // @ts-ignore
              rotation.w
            ),
            "XYZ"
          );
          if (!spriteComponent.flipX) {
            spriteComponent.spriteMap.repeat.set(1 / spriteComponent.spriteMap.userData.columns, 1 / spriteComponent.spriteMap.userData.rows);
            spriteComponent.spriteMap.center = new Vector2(0, 1);
          } else {
            spriteComponent.spriteMap.repeat.set(-1 / spriteComponent.spriteMap.userData.columns, 1 / spriteComponent.spriteMap.userData.rows);
            spriteComponent.spriteMap.center = new Vector2(0.5, 1);
          }
          spriteComponent.instance?.position.set(
            x2,
            y3,
            z2
          );
        }
      );
      this.query("remove").forEach(
        (entity2) => {
          const spriteComponent = entity2.components.get("sprite" /* Sprite */);
          if (spriteComponent.instance) {
            spriteComponent.instance.remove();
            spriteComponent.instance.geometry.dispose();
            spriteComponent.instance.material.dispose();
            scene.instance.remove(spriteComponent.instance);
          }
        }
      );
      const validEntities = scene.entitiesManager.getAllWithComponents(...this.queryComponents);
      validEntities.forEach((entity2) => {
        const spriteComponent = entity2.components.get("sprite" /* Sprite */);
        const { position: { x: x2, y: y3, z: z2 } } = entity2.components.get(
          "transform" /* Transform */
        );
        if (spriteComponent.instance && spriteComponent.animation) {
          spriteComponent.instance?.position.set(x2, y3, z2);
          const { active, sequences, sequence, ticksPerFrame, lastSequence } = spriteComponent.animation;
          if (active) {
            if (!lastSequence || lastSequence !== sequence.name) {
              console.log("sequence changed");
              spriteComponent.animation.tickCount = 0;
              spriteComponent.animation.lastSequence = sequence.name;
              spriteComponent.animation.sequence.currentFrame = 0;
            } else {
              spriteComponent.animation.tickCount += 1;
            }
            if (spriteComponent.animation.tickCount > ticksPerFrame) {
              spriteComponent.animation.tickCount = 0;
              if (sequences[sequence.name][1] - 1 <= sequence.currentFrame) {
                spriteComponent.animation.sequence.currentFrame = 0;
              } else {
                spriteComponent.animation.sequence.currentFrame += 1;
              }
            }
            const { width, height } = spriteComponent;
            const columns = spriteComponent.spriteMap.source.data.width / width;
            const rows = spriteComponent.spriteMap.source.data.height / height;
            const idx = Object.entries(sequences).findIndex(
              ([key, value]) => key === sequence.name
            );
            if (!spriteComponent.flipX) {
              spriteComponent.spriteMap.offset.x = sequence.currentFrame / columns;
            } else {
              spriteComponent.spriteMap.offset.x = -(sequence.currentFrame / columns);
            }
            spriteComponent.spriteMap.offset.y = -idx / rows;
          }
        }
      });
    });
  }
  getScaled(value) {
    return value * 1 / this.context.scaleFactor;
  }
  randomizeMatrix(matrix) {
    const position = new Vector3();
    const quaternion = new Quaternion();
    const scale = new Vector3(1, 1, 1);
    position.x = Math.random() * 10 - 0;
    position.z = Math.random() * 10 - 0;
    matrix.compose(position, quaternion, scale);
  }
};

