var AudioSystem = class extends AbstractSystem {
  audioListener = new AudioListener();
  audioListenerReady = false;
  name = "AudioSystem";
  async start() {
    spelDebug.log("[Audio System]::Start");
    this.queryComponents = [
      "audio" /* Audio */
    ];
  }
  async run() {
    const scenes = this.context.sceneManager.renderScenes;
    scenes.forEach((scene) => {
      if (!this.audioListenerReady && scene.mainCamera && scene.mainCamera.instance) {
        console.log("[Audio System] - Add Listener");
        scene.mainCamera.instance?.add(this.audioListener);
        this.audioListenerReady = true;
        const validEntities = scene.entitiesManager.getAllWithComponents(...this.queryComponents);
        validEntities.forEach((entity2) => {
          const audioComponent = entity2.components.get("audio" /* Audio */);
          if (audioComponent.autoPlay && audioComponent.instance) {
            console.log(audioComponent.instance);
            Object.values(audioComponent.instance)[0]?.play();
          }
        });
      }
      this.query("add").filter((entity2) => entity2.visible).forEach(
        (entity2) => {
          const audioComponent = entity2.components.get("audio" /* Audio */);
          if (audioComponent.instance == null) {
            audioComponent.instance = {};
            for (const source of audioComponent.source) {
              const audioBuffer = resourcesLoader.resources.audios.get(source);
              if (audioBuffer) {
                audioComponent.instance[source] = new PositionalAudio(this.audioListener);
                audioComponent.instance[source].setBuffer(audioBuffer);
                audioComponent.instance[source].setVolume(1);
                audioComponent.instance[source].setRefDistance(audioComponent.refDistance);
                audioComponent.instance[source].setLoop(audioComponent.loop);
                if (audioComponent.maxDistance) {
                  audioComponent.instance[source].setMaxDistance(audioComponent.maxDistance);
                }
                if (audioComponent.appendTo) {
                  const component = entity2.components.get(audioComponent.appendTo === "Mesh" ? "mesh" /* Mesh */ : "sprite" /* Sprite */);
                  component.instance?.add(audioComponent.instance[source]);
                }
              }
            }
            console.log(audioComponent.instance);
          }
        }
      );
    });
  }
};

