var LightSystem = class extends AbstractSystem {
  name = "LightSystem";
  async start(deltaTime3) {
    spelDebug.log("[Light System]::Start");
    this.queryComponents = [
      "transform" /* Transform */,
      "light" /* Light */
    ];
  }
  async run() {
    const scenes = this.context.sceneManager.renderScenes;
    if (scenes.length === 0) {
      return;
    }
    scenes.forEach((scene) => {
      this.query("add").filter((entity2) => entity2.visible).forEach(
        (entity2) => {
          const lightComponent = entity2.components.get("light" /* Light */);
          const { position: { x: x2, y: y3, z: z2 }, rotation } = entity2.components.get(
            "transform" /* Transform */
          );
          if (!lightComponent.instance) {
            switch (lightComponent.light) {
              case "point":
                lightComponent.instance = new PointLight(
                  16777215,
                  1,
                  500
                );
                break;
              case "directional":
                lightComponent.instance = new DirectionalLight(
                  16777215,
                  lightComponent.intensity
                );
                scene.addChild(new DirectionalLightHelper(lightComponent.instance, 5));
                break;
              case "hemisphere":
                lightComponent.instance = new HemisphereLight(
                  16777215,
                  16777215,
                  lightComponent.intensity || 1
                );
                break;
              case "ambient":
                lightComponent.instance = new AmbientLight(16777215);
                break;
              case "spot":
                lightComponent.instance = new PointLight(16777215);
                lightComponent.instance.shadow.mapSize.width = 1024;
                lightComponent.instance.shadow.mapSize.height = 1024;
                break;
              default:
                break;
            }
            if (lightComponent.groundColorHSL && lightComponent.light === "hemisphere") {
              const [c1, c2, c3] = lightComponent.groundColorHSL;
              lightComponent.instance.groundColor.setHSL(c1, c2, c3);
            }
            if (lightComponent.colorHSL) {
              const [c1, c2, c3] = lightComponent.colorHSL;
              lightComponent.instance.color.setHSL(c1, c2, c3);
            }
            if (lightComponent.colorHSL && lightComponent.light === "directional") {
              const [c1, c2, c3] = lightComponent.colorHSL;
              lightComponent.instance.multiplyScalar = lightComponent.multiplyScalar;
            }
            if (lightComponent.instance && lightComponent.castShadow && lightComponent.light !== "hemisphere") {
              console.log(lightComponent.light);
              lightComponent.instance.castShadow = true;
              lightComponent.instance.shadow.mapSize.width = 8048;
              lightComponent.instance.shadow.mapSize.height = 8048;
              console.log(lightComponent.instance);
              const d2 = 150;
              lightComponent.instance.shadow.camera.left = -d2;
              lightComponent.instance.shadow.camera.right = d2;
              lightComponent.instance.shadow.camera.top = d2;
              lightComponent.instance.shadow.camera.bottom = -d2;
              lightComponent.instance.shadow.camera.far = 250;
              lightComponent.instance.shadow.bias = -1e-4;
            }
            scene.instance.add(lightComponent.instance);
          }
          if (lightComponent.instance) {
            lightComponent.instance?.position.set(x2, y3, z2);
            lightComponent.instance?.setRotationFromEuler(
              new Euler(
                MathUtils.degToRad(rotation.x),
                rotation.y * Math.PI / 180,
                MathUtils.degToRad(rotation.z),
                "XYZ"
              )
            );
          }
        }
      );
    });
  }
};

