var SYSTEMS = {
  // Tilemap: TilemapSystem,
  MeshSystem,
  PhysicsSystem,
  // PhysicsDebugSystem: PhysicsDebugSystem,
  // ShapeSystem: ShapeSystem,
  SpriteSystem,
  AudioSystem,
  // FbxAnimationSystem: FbxAnimationSystem,
  LightSystem,
  InterfaceSystem,
  // DebugSystem: DebugSystem,
  // EntitySystem: EntitySystem,
  ScriptSystem,
  CameraSystem
};
var loadSystem = (engine, config3 = {}) => {
  let tempSystems = { ...SYSTEMS };
  if ("include" in config3) {
    tempSystems = {};
    config3.include?.forEach((item) => {
      tempSystems[item] = SYSTEMS[item];
    });
  } else if ("exclude" in config3) {
    config3.exclude?.forEach((item) => {
      delete tempSystems[item];
    });
  }
  return new Map(
    Object.entries(tempSystems).map(([key, system]) => [key, new system(engine)])
  );
};

