var FloorScript = class extends AbstractScript {
  mesh;
  dissolveThreshold;
  start() {
    console.log("floor script started");
    this.dissolveThreshold = uniform2(0.5);
    const baseColor = uniform2(vec32(0, 0.5, 1));
    const edgeColor = uniform2(vec32(1, 0.5, 0));
    const blobEffect = sin2(add2(mul2(positionLocal2.y, float2(5)), mul2(time2, float2(2))));
    const dissolveFactor = step2(this.dissolveThreshold, add2(positionLocal2.y, blobEffect));
    const edgeFactor = step2(add2(this.dissolveThreshold, float2(-0.1)), add2(positionLocal2.y, blobEffect));
    const finalColor = mix2(edgeColor, baseColor, dissolveFactor);
    this.mesh.instance.children[0].material.colorNode = vec42(finalColor, mul2(dissolveFactor, edgeFactor));
    this.mesh.instance.children[0].material.transparent = true;
  }
  update() {
    this.dissolveThreshold.value = Math.abs(Math.sin(time2.value * 0.5));
  }
};

